using Microsoft.AspNetCore.Mvc;
using System.ComponentModel.DataAnnotations;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace Api.Controllers;

[ApiController]
[Route("calculations")]
public class CalculationsController : ControllerBase
{
    private readonly CalculationService _calculationService;

    public CalculationsController(CalculationService calculationService)
    {
        _calculationService = calculationService;
    }

    [HttpPost]
    [ProducesResponseType(typeof(CalculationResponse), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status500InternalServerError)]
    public async Task<IActionResult> CreateCalculation([FromBody] CreateCalculationRequest request)
    {
        if (request is null || request.FirstNumber is null || request.SecondNumber is null)
        {
            return BadRequest(new ProblemDetails
            {
                Type = "https://tools.ietf.org/html/rfc9457",
                Title = "Bad Request",
                Status = StatusCodes.Status400BadRequest,
                Detail = "Поля first_number и second_number обязательны.",
                Instance = "/calculations"
            });
        }

        try
        {
            var result = await _calculationService.CreateCalculationAsync(request.FirstNumber.Value, request.SecondNumber.Value);
            return Ok(result);
        }
        catch (InvalidOperationException ex)
        {
            return BadRequest(new ProblemDetails
            {
                Type = "https://tools.ietf.org/html/rfc9457",
                Title = "Bad Request",
                Status = StatusCodes.Status400BadRequest,
                Detail = ex.Message,
                Instance = "/calculations"
            });
        }
        catch (Exception ex)
        {
            return StatusCode(StatusCodes.Status500InternalServerError, new ProblemDetails
            {
                Type = "https://tools.ietf.org/html/rfc9457",
                Title = "Internal Server Error",
                Status = StatusCodes.Status500InternalServerError,
                Detail = ex.Message,
                Instance = "/calculations"
            });
        }
    }
}

using System.Text.Json.Serialization;

namespace Api.Dtos;

public class CreateCalculationRequest
{
    [JsonPropertyName("first_number")]
    public decimal? FirstNumber { get; set; }

    [JsonPropertyName("second_number")]
    public decimal? SecondNumber { get; set; }
}

using System.Text.Json.Serialization;

namespace Api.Dtos;

public class CalculationResponse
{
    [JsonPropertyName("id")]
    public string Id { get; set; } = string.Empty;

    [JsonPropertyName("first_number")]
    public decimal FirstNumber { get; set; }

    [JsonPropertyName("second_number")]
    public decimal SecondNumber { get; set; }

    [JsonPropertyName("result")]
    public decimal Result { get; set; }

    [JsonPropertyName("created_at")]
    public DateTime CreatedAt { get; set; }
}

using System.Text.Json.Serialization;

namespace Api.Dtos;

public class ProblemDetails
{
    [JsonPropertyName("type")]
    public string? Type { get; set; }

    [JsonPropertyName("title")]
    public string? Title { get; set; }

    [JsonPropertyName("status")]
    public int? Status { get; set; }

    [JsonPropertyName("detail")]
    public string? Detail { get; set; }

    [JsonPropertyName("instance")]
    public string? Instance { get; set; }
}

using Api.Entities;
using Api.Dtos;

namespace Api.Services;

public class CalculationService
{
    private readonly InMemoryCalculationStore _store;

    public CalculationService(InMemoryCalculationStore store)
    {
        _store = store;
    }

    public Task<CalculationResponse> CreateCalculationAsync(decimal firstNumber, decimal secondNumber)
    {
        var calculation = new Calculation
        {
            Id = Guid.NewGuid().ToString(),
            FirstNumber = firstNumber,
            SecondNumber = secondNumber,
            Result = firstNumber + secondNumber,
            CreatedAt = DateTime.UtcNow
        };

        _store.Add(calculation);

        return Task.FromResult(new CalculationResponse
        {
            Id = calculation.Id,
            FirstNumber = calculation.FirstNumber,
            SecondNumber = calculation.SecondNumber,
            Result = calculation.Result,
            CreatedAt = calculation.CreatedAt
        });
    }
}

using Api.Entities;

namespace Api.Services;

public class InMemoryCalculationStore
{
    private readonly List<Calculation> _calculations = new();
    private readonly object _lock = new();

    public void Add(Calculation calculation)
    {
        lock (_lock)
        {
            _calculations.Add(calculation);
        }
    }

    public Calculation? GetById(string id)
    {
        lock (_lock)
        {
            return _calculations.FirstOrDefault(c => c.Id == id);
        }
    }

    public IReadOnlyList<Calculation> GetAll()
    {
        lock (_lock)
        {
            return _calculations.ToList();
        }
    }
}

namespace Api.Entities;

public class Calculation
{
    public string Id { get; set; } = string.Empty;
    public decimal FirstNumber { get; set; }
    public decimal SecondNumber { get; set; }
    public decimal Result { get; set; }
    public DateTime CreatedAt { get; set; }
}
